pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount) public {
        // Constrain deposit to a sensible range to avoid overflow and ensure the reference can withdraw
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount <= type(uint128).max);

        // Fund the contract by calling the fallback
        address donor = makeAddr("donor");
        vm.deal(donor, depositAmount);
        vm.prank(donor);
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        uint256 balanceBefore = address(c).balance;
        assertTrue(balanceBefore > 0, "balance must be positive");

        // Owner withdraws all
