pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, uint256 withdrawalAmount) public {
        // restrict deposit amount to something that can be sent and accumulate
        bound(depositAmount, 1, 100 ether);
        // the owner is this contract itself, so we can receive Ether
        // also restrict withdrawAll to be called with at least some balance present
        // for the bug to manifest, the contract must have some balance
        vm.deal(address(this), depositAmount);
        // we use prank to make this contract the owner (it already is)
        vm.prank(address(this));
        (bool ok,) = address(c).call{value: depositAmount}("");
        require(ok, "deposit failed");

        uint256 balanceBefore = address(c).balance;
        uint256 ownerBefore = address(this).balance;

        // now call withdrawAll (this contract is owner)
        uint256 gasBefore = gasleft();
        try c.withdrawAll() {
            // success path: the buggy version will also succeed, but with different balance change
            uint256 balanceAfter = address(c).balance;
            uint256 ownerAfter = address(this).balance;

            // universal rule: owner's balance must strictly increase by at least the amount withdrawn,
            // which should be the full contract balance before withdrawal
            // Since withdrawAll is supposed to withdraw(address(this).balance),
            // the owner's balance should increase by exactly balanceBefore, and contract balance should be 0.
            // The bug makes it call withdraw(0), so ownerAfter == ownerBefore and balanceAfter == balanceBefore.
            // Therefore the rule: ownerAfter > ownerBefore && balanceAfter == 0 (for correct)
            // But we need a rule that the reference ALWAYS satisfies and the bug FAILS.
            // Reference: after a successful withdrawAll, address(this).balance > ownerBefore.
            // Bug: after a successful withdrawAll, address(this).balance == ownerBefore (gain is 0).
            assertTrue(ownerAfter > ownerBefore);
        } catch {
            // if the call itself reverts, we don't assert (this could happen for edge cases, but should not with proper setup)
            // The rule is about successful calls only.
            // The reference won't revert here; bug won't revert either, both succeed.
            // So this path won't be triggered for our admissible inputs.
            // We can still safely return without assertion.
        }
    }
}

