        // After withdrawAll, the correct contract transfers the entire balance, leaving zero.
        // The buggy contract calls withdraw(0), leaving the balance unchanged.
        // Thus for the correct contract, balanceAfter == 0 for every input;
        // for the buggy contract, balanceAfter == balanceBefore > 0 for some input.
        assertTrue(balanceAfter == 0);
    }
}

