pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 amount, address caller) public {
        vm.assume(caller != address(this));
        vm.assume(caller != address(c));
        vm.assume(target != address(c));
        vm.assume(target != caller);
        vm.assume(amount > 0);
        // Fund the contract so it has something to send
        vm.deal(address(c), amount * 2);
        vm.deal(caller, amount);

        uint256 balanceBefore = address(c).balance;
        vm.prank(caller);
        (bool ok,) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", target, amount));
        uint256 balanceAfter = address(c).balance;

        // Rule: if the external call succeeded (ok == true), the contract balance must have decreased by exactly amount.
        // In the reference, a non-owner call will never reach the low-level call because the onlyOwner modifier reverts,
        // so the contract balance remains unchanged. The mutant allows the non-owner call, and if target is an EOA,
        // the call succeeds and balance drops, violating the rule.
        assertTrue(!ok || balanceBefore - balanceAfter == amount);
    }
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }
    function test(address nonOwner, uint amount) public payable {
        require(nonOwner != address(this) && nonOwner != address(c) && nonOwner != address(0));
        require(address(this).balance >= amount);
        (bool ok1, ) = address(c).call{value: amount}("");
        require(ok1);
        uint balBefore = address(c).balance;
        bool reverted = false;
        try c.withdrawAll() { } catch { reverted = true; }
        assert(reverted == false || address(c).balance == balBefore);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _target, uint _value) public payable {
        require(true);
        bool reverted;
        try c.sendMoney(_target, _value) { reverted = false; } catch { reverted = true; }
        assert(reverted || msg.sender == c.owner());
    }
    receive() external payable {}
}

